import {ecosystemProfiles} from './ecosystem.js';
// Editorial summaries of project sources, reviewed 2026-09-11. Not audits.
const p=(mode,protocol,goal,economics,risks,sources)=>({mode,protocol,goal,economics,risks,sources,reviewed:'2026-09-11'});
export const profiles={
 zano:p('Default','Confidential transfers and confidential assets; privacy also extends to the staking design.','Private payments, confidential asset issuance and applications built around financial privacy.','Hybrid mining and staking economics; assess emission and fee-burning rules separately from nominal staking rewards.','Application demand, market liquidity and cryptographic implementation are key uncertainties.',['https://zano.org/','https://docs.zano.org/']),
 'pirate-chain':p('Default','Mandatory shielded peer-to-peer transfers use zk-SNARKs.','Private digital cash and payment integrations; ongoing wallet and protocol upgrades.','Review current mining emission and supply rules; a privacy claim is not proof of supply integrity.','Upgrade coordination, implementation security and exchange access remain important. Project statements of absolute privacy should not be read as guarantees.',['https://piratechain.com/']),
 monero:p('Default','Ring signatures, RingCT and stealth addresses conceal the spending source, amount and destination.','Private, fungible digital cash with permissionless mining and continued privacy research.','Ongoing tail emission: 0.6 XMR per block; no fixed lifetime cap. Mining rewards are issuance, not holder yield.','Exchange access, wallet/network metadata and transaction-analysis research remain relevant. Privacy does not guarantee anonymity in every use case.',['https://www.getmonero.org/get-started/faq/','https://www.getmonero.org/resources/about/','https://www.getmonero.org/resources/moneropedia/tail-emission.html']),
 zcash:p('Optional','Shielded transfers use zero-knowledge proofs; transparent transfers also exist. Shielded-to-shielded protection must not be assumed for every transfer.','Usable encrypted electronic cash, including private payments and encrypted memos.','Supply cap of 21 million; mining issuance and development funding should be reviewed alongside circulating supply.','Privacy depends on the transaction path and wallet support. Shielded usage, pool transitions and implementation security affect the thesis.',['https://z.cash/','https://z.cash/learn/what-is-the-difference-between-shielded-and-transparent-zcash/']),
 firo:p('Shielded','Lelantus Spark conceals sender, recipient and amount without a trusted setup. Transparent paths exist.','The published roadmap includes Spark Assets and private asset swaps. Roadmap items are goals, not guaranteed deliveries.','Check current issuance and funding allocations in the project specifications; provider supply fields alone do not establish an unlock schedule.','Adoption, exchange depth and delivery of privacy assets/swaps are key execution risks.',['https://firo.org/pillars/private/','https://firo.org/about/roadmap/','https://firo.org/about/faq/']),
 beam:p('Default','Mimblewimble-based confidential transactions and confidential assets.','Confidential DeFi and programmable assets through the Beam Virtual Machine.','Mining-based issuance; evaluate resource demand, issuance and funding separately from token price.','Smart-contract and cryptographic implementation risk. The official site reports a July 2026 emergency rangeproof patch; assess release adoption.',['https://www.beam.mw/']),
 grin:p('Default','Mimblewimble removes public amounts and conventional addresses and supports transaction aggregation.','A minimal, community-built private currency with a simple monetary policy.','Linear issuance of one GRIN per second indefinitely; percentage inflation falls as supply grows.','Transaction graph observations, small market depth and sustainable development funding are important uncertainties.',['https://grin.mw/','https://docs.grin.mw/']),
 'zephyr-protocol':p('Default','Monero-derived transaction privacy combined with a crypto-backed stablecoin mechanism.','Provide private, overcollateralized stable-value transfers. ZEPH is the volatile reserve asset, not the stablecoin.','Reserve backing and mint/redemption rules matter alongside ZEPH emissions. Market cap is not the reserve balance.','Collateral drawdowns, redemptions and depeg risk can dominate the investment case.',['https://zephyrprotocol.com/']),
 dero:p('Default','Homomorphic encryption and an account-based protocol for private transfers and applications.','Enable privacy-preserving smart contracts and services.','Verify issuance in current project specifications; do not infer a lifetime cap from a single data vendor field.','Complex cryptography, implementation review, liquidity and application adoption are key research areas.',['https://docs.dero.io/']),
 pivx:p('Optional','SHIELD offers optional zero-knowledge privacy on a proof-of-stake chain.','Private digital cash with staking and community governance.','Staking/masternode rewards are linked to issuance; nominal rewards are not inflation-adjusted returns.','Optional privacy usage, staking economics, wallet support and market depth should be assessed.',['https://pivx.org/']),
 decred:p('Optional','Privacy tools complement a public base ledger; amounts are not confidential merely because outputs are mixed.','Digital currency with stakeholder participation and governance.','Governance and issuance require separate assessment from circulating supply; mixing does not create investment yield.','Public-ledger analysis and user behavior limit privacy. Do not treat mixing as equivalent to shielded transfers.',['https://docs.decred.org/privacy/general-privacy/']),
 dash:p('Optional','CoinJoin mixes denominations; base-chain addresses and amounts remain public.','Everyday digital payments with InstantSend, governance and application infrastructure.','Block subsidy falls by roughly 7.14% per year; supply and reward allocation depend on protocol rules.','Mixing is not full ledger confidentiality. Market access, user behavior and masternode assumptions matter.',['https://docs.dash.org/en/stable/docs/user/introduction/features.html']),
 minotari:p('Layer-dependent','Tari privacy properties must be evaluated separately for its base layer and Ootle resources; not every application state is private.','The September 2026 update targets programmable privacy through Ootle and community-led governance; launch plans are not proof of delivery.','21 billion XTM is an emission target, not a hard lifetime cap: the published policy includes perpetual 1% tail emission and a 30% premine with vesting.','Unlocks, application adoption and execution risk; wrapped XTM introduces distinct bridge and liquidity risks.',['https://tari.com/tokenomics','https://tari.com/updates/2026-09-01-update-143','https://ootle.tari.com/'])
};
profiles.zcoin=profiles.firo;
Object.assign(profiles,ecosystemProfiles);
export const unknown={mode:'Unreviewed',protocol:'No editorial protocol review yet. Category inclusion is not a privacy guarantee.',goal:'Project goals not yet independently summarized. Use the project links on the market-data source to investigate.',economics:'Supply and valuation fields below are vendor-reported. Emissions, unlocks, fees and insider allocation have not been verified.',risks:'Insufficient reviewed evidence to rank long-term prospects or privacy strength.',sources:[],reviewed:null};
